def max_product(num_str: str, N: int, K: int) -> int:
    # Ensure N matches length of num_str, adjust if needed
    N = len(num_str)
    # Cannot insert more multiplication signs than gaps
    if K > N - 1:
        K = N - 1
    if K < 0:
        return 0
    # Quick return if no multiplication signs
    if K == 0:
        return int(num_str)
    # Precompute integer values for all substrings
    nums = [[0] * (N + 1) for _ in range(N)]
    for i in range(N):
        val = 0
        for j in range(i, N):
            val = val * 10 + int(num_str[j])
            nums[i][j + 1] = val
    # dp[i][k] = max product for first i digits using k multiplication signs
    dp = [[0] * (K + 1) for _ in range(N + 1)]
    # Base case: 0 signs
    for i in range(1, N + 1):
        dp[i][0] = nums[0][i]
    # Fill DP for k >= 1
    for i in range(1, N + 1):
        max_k = min(K, i - 1)  # can only place at most i-1 signs in i digits
        for k in range(1, max_k + 1):
            best = 0
            # last segment starts at position j (0-indexed) up to i-1
            # need j >= k because first j digits must accommodate k-1 signs
            for j in range(k, i):
                prod = dp[j][k - 1] * nums[j][i]
                if prod > best:
                    best = prod
            dp[i][k] = best
    return dp[N][K]

def max_product(num_str: str, N: int, K: int) -> int:
