    sub_num = [[0] * (N + 1) for _ in range(N + 1)]
    for i in range(N):
        val = 0
        for j in range(i + 1, N + 1):
            val = val * 10 + (ord(num_str[j - 1]) - 48)
            sub_num[i][j] = val

    # dp[i][k] – maximum product for prefix of length i with k cuts
    dp = [[0] * (K + 1) for _ in range(N + 1)]

    # Base: 0 cuts -> whole number
    for i in range(1, N + 1):
        dp[i][0] = sub_num[0][i]

    for k in range(1, K + 1):
        for i in range(1, N + 1):
            # Need at least k digits before we can place k cuts
            best = 0
            # j is the position where the last number starts (0-based)
            for j in range(k, i):
                val = dp[j][k - 1] * sub_num[j][i]
                if val > best:
                    best = val
            dp[i][k] = best

    return dp[N][K] if K <= N - 1 else 0

def max_product(num_str: str, N: int, K: int) -> int:
    from functools import lru_cache

    n = len(num_str)
    if K < 0 or K > n - 1:
        return 0

    @lru_cache(maxsize=None)
    def dfs(pos: int, cuts_left: int) -> int:
        if cuts_left == 0:
            return int(num_str[pos:])
        max_prod = 0
        # choose next cut point i (exclusive end of current segment)
        for i in range(pos + 1, n - cuts_left + 1):
            left = int(num_str[pos:i])
            right = dfs(i, cuts_left - 1)
            prod = left * right
            if prod > max_prod:
                max_prod = prod
        return max_prod

    return dfs(0, K)

