def count_partitions(n: int, k: int, x: int) -> int:
    """
    Count the number of ways to partition an integer n into k parts,
    where each part is at least x and the order of parts does not matter.
    """
    # Reduce the problem: subtract the minimum value x from each part.
    n_prime = n - k * x
    if n_prime < 0:
        return 0

    # dp[i][j] = number of partitions of i into parts <= j
    # (which equals number of partitions of i into at most j parts)
    dp = [[0] * (k + 1) for _ in range(n_prime + 1)]
    for j in range(k + 1):
        dp[0][j] = 1  # One way to partition 0 (empty sum)

    for i in range(1, n_prime + 1):
        dp[i][0] = 0  # Cannot partition a positive number with parts <= 0

    for i in range(1, n_prime + 1):
        for j in range(1, k + 1):
            dp[i][j] = dp[i][j - 1]
            if i >= j:
                dp[i][j] += dp[i - j][j]

    return dp[n_prime][k]

