def min_groups(w, n, prices):
    prices.sort()
    i, j = 0, n - 1
    groups = 0
    while i <= j:
        if i == j:
            groups += 1
            break
        if prices[i] + prices[j] <= w:
            i += 1
            j -= 1
        else:
            j -= 1
        groups += 1
    return groups

def hanoi_double_iterative(n: int) -> int:
    if n <= 0:
        return 0
    moves = 2
    for _ in range(2, n + 1):
        moves = 2 * moves + 2
    return moves

